module gear_ratio_solver (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [7:0] n0, d0,\n    input wire [7:0] n1, d1,\n    input wire [7:0] n2, d2,\n    input wire [7:0] n3, d3,\n    input wire [7:0] n4, d4,\n    input wire [7:0] n5, d5,\n    input wire [7:0] n6, d6,\n    input wire [7:0] n7, d7,\n    input wire [7:0] n8, d8,\n    input wire [7:0] n9, d9,\n    input wire [7:0] n10, d10,\n    input wire [7:0] n11, d11,\n    output reg [13:0] front1, front2,\n    output reg [13:0] rear1, rear2, rear3, rear4, rear5, rear6,\n    output reg valid,\n    output reg done\n);\n\n// State encoding\nlocalparam [2:0] IDLE    = 3'b000;\nlocalparam [2:0] LOAD    = 3'b001;\nlocalparam [2:0] PROCESS = 3'b010;\nlocalparam [2:0] OUTPUT  = 3'b011;\nlocalparam [2:0] ERROR   = 3'b100;\n\nreg [2:0] state, next_state;\nreg [3:0] idx;\nreg [7:0] num [0:11];\nreg [7:0] den [0:11];\nreg [7:0] num1_reg, num2_reg;\nreg [1:0] num_count;\nreg [7:0] den_table [0:5];\nreg [2:0] den_count;\nreg error_flag;\nreg [3:0] proc_idx;\ninteger i;\n\n// State transition\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        state <= IDLE;\n        idx <= 4'd0;\n        proc_idx <= 4'd0;\n        num1_reg <= 8'd0;\n        num2_reg <= 8'd0;\n        num_count <= 2'd0;\n        den_count <= 3'd0;\n        error_flag <= 1'b0;\n        front1 <= 14'd0;\n        front2 <= 14'd0;\n        rear1 <= 14'd0;\n        rear2 <= 14'd0;\n        rear3 <= 14'd0;\n        rear4 <= 14'd0;\n        rear5 <= 14'd0;\n        rear6 <= 14'd0;\n        valid <= 1'b0;\n        done <= 1'b0;\n        for (i = 0; i < 12; i = i + 1) begin\n            num[i] <= 8'd0;\n            den[i] <= 8'd0;\n        end\n        for (i = 0; i < 6; i = i + 1) begin\n            den_table[i] <= 8'd0;\n        end\n    end else begin\n        state <= next_state;\n        \n        case (state)\n            IDLE: begin\n                done <= 1'b0;\n                valid <= 1'b0;\n                if (start) begin\n                    idx <= 4'd0;\n                    num_count <= 2'd0;\n                    den_count <= 3'd0;\n                    error_flag <= 1'b0;\n                    proc_idx <= 4'd0;\n                    num1_reg <= 8'd0;\n                    num2_reg <= 8'd0;\n                    for (i = 0; i < 6; i = i + 1) begin\n                        den_table[i] <= 8'd0;\n                    end\n                end\n            end\n            \n            LOAD: begin\n                if (idx < 4'd12) begin\n                    case (idx)\n                        4'd0: begin num[0] <= n0; den[0] <= d0; end\n                        4'd1: begin num[1] <= n1; den[1] <= d1; end\n                        4'd2: begin num[2] <= n2; den[2] <= d2; end\n                        4'd3: begin num[3] <= n3; den[3] <= d3; end\n                        4'd4: begin num[4] <= n4; den[4] <= d4; end\n                        4'd5: begin num[5] <= n5; den[5] <= d5; end\n                        4'd6: begin num[6] <= n6; den[6] <= d6; end\n                        4'd7: begin num[7] <= n7; den[7] <= d7; end\n                        4'd8: begin num[8] <= n8; den[8] <= d8; end\n                        4'd9: begin num[9] <= n9; den[9] <= d9; end\n                        4'd10: begin num[10] <= n10; den[10] <= d10; end\n                        4'd11: begin num[11] <= n11; den[11] <= d11; end\n                    endcase\n                    idx <= idx + 4'd1;\n                end\n            end\n            \n            PROCESS: begin\n                if (proc_idx < 4'd12) begin\n                    // Numerator processing\n                    if (num[proc_idx] != num1_reg && num[proc_idx] != num2_reg) begin\n                        if (num_count == 2'd0) begin\n                            num1_reg <= num[proc_idx];\n                            num_count <= 2'd1;\n                        end else if (num_count == 2'd1) begin\n                            num2_reg <= num[proc_idx];\n                            num_count <= 2'd2;\n                        end else begin\n                            error_flag <= 1'b1;\n                        end\n                    end\n                    \n                    // Denominator processing\n                    if (den[proc_idx] != den_table[0] && den[proc_idx] != den_table[1] &&\n                        den[proc_idx] != den_table[2] && den[proc_idx] != den_table[3] &&\n                        den[proc_idx] != den_table[4] && den[proc_idx] != den_table[5]) begin\n                        \n                        if (den_count < 3'd6) begin\n                            den_table[den_count] <= den[proc_idx];\n                            den_count <= den_count + 3'd1;\n                        end else begin\n                            error_flag <= 1'b1;\n                        end\n                    end\n                    \n                    proc_idx <= proc_idx + 4'd1;\n                end\n            end\n            \n            OUTPUT: begin\n                front1 <= num1_reg;\n                front2 <= num2_reg;\n                rear1 <= den_table[0];\n                rear2 <= den_table[1];\n                rear3 <= den_table[2];\n                rear4 <= den_table[3];\n                rear5 <= den_table[4];\n                rear6 <= den_table[5];\n                valid <= 1'b1;\n                done <= 1'b1;\n            end\n            \n            ERROR: begin\n                valid <= 1'b0;\n                done <= 1'b1;\n            end\n        endcase\n    end\nend\n\n// Next state logic\nalways @(*) begin\n    next_state = state;\n    case (state)\n        IDLE: next_state = (start) ? LOAD : IDLE;\n        LOAD: next_state = (idx == 4'd12) ? PROCESS : LOAD;\n        PROCESS: begin\n            if (proc_idx == 4'd12) begin\n                if (error_flag || num_count != 2'd2 || den_count != 3'd6) begin\n                    next_state = ERROR;\n                end else begin\n                    next_state = OUTPUT;\n                end\n            end\n        end\n        OUTPUT, ERROR: next_state = IDLE;\n        default: next_state = IDLE;\n    endcase\nend\n\nendmodule